package usernamepolicy

import (
	_ "embed"
	"sync"
)

// Official lexicon, byte-for-byte policy/dist/policy-2026092301.json
// from tellomi/tellomi. Do not edit this file. It is the historical
// 470-rule baseline. Runtime checks do not use it.
//
//go:embed policy/policy-2026092301.json
var officialPolicy []byte

// Current lexicon, byte-for-byte policy/dist/policy-2026110602.json
// from tellomi/tellomi (1024 rules, 52 allow entries). It already
// contains the appendix C / D-56 names that overlay-d56.json added on
// top of policy-2026092301, plus regions/cn politics. Do not edit it
// here and do not stack overlay-d56.json on top: the terms would duplicate.
//
//go:embed policy/policy-2026110602.json
var currentPolicy []byte

// D-56 names that policy-2026092301 does not already reserve.
// Appendix C placeholders are still generated from this spec.
// Runtime checks use currentPolicy instead.
//
//go:embed policy/overlay-d56.json
var overlayPolicy []byte

var (
	officialOnce sync.Once
	officialEng  *Engine
	officialErr  error

	currentOnce sync.Once
	currentEng  *Engine
	currentErr  error
)

func officialEngine() *Engine {
	officialOnce.Do(func() {
		officialEng, officialErr = Load(officialPolicy)
	})
	if officialErr != nil {
		panic(officialErr)
	}
	return officialEng
}

func currentEngine() *Engine {
	currentOnce.Do(func() {
		currentEng, currentErr = Load(currentPolicy)
	})
	if currentErr != nil {
		panic(currentErr)
	}
	return currentEng
}

// runtimeEngine is what RejectUser and RejectDisplay consult.
// policy-2026110602 already covers D-56, so the older overlay is not merged in.
func runtimeEngine() *Engine { return currentEngine() }

func embeddedEngine() *Engine { return runtimeEngine() }
